          textAlign: TextAlign.center,
        ),
        const SizedBox(height: 20),
        Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            Text(
              "Recipient Wallet",
              style: STextStyles.desktopTextExtraExtraSmall(context).copyWith(
                color: Theme.of(
                  context,
                ).extension<StackColors>()!.textFieldActiveSearchIconRight,
              ),
            ),
            if (AppConfig.isStackCoin(
              ref.watch(
                desktopExchangeModelProvider.select(
                  (value) => value!.receiveTicker,
                ),
              ),
            ))
              CustomTextButton(
                text: "Choose from ${AppConfig.prefix}",
                onTap: selectRecipientAddressFromStack,
              ),
          ],
        ),
        const SizedBox(height: 10),
        ClipRRect(
          borderRadius: BorderRadius.circular(
            Constants.size.circularBorderRadius,
          ),
          child: TextField(
            onTap: () {},
            key: const Key("recipientExchangeStep2ViewAddressFieldKey"),
            controller: _toController,
            readOnly: false,
            autocorrect: false,
            enableSuggestions: false,
            // inputFormatters: <TextInputFormatter>[
            //   FilteringTextInputFormatter.allow(RegExp("[a-zA-Z0-9]{34}")),
            // ],
            toolbarOptions: const ToolbarOptions(
              copy: false,
              cut: false,
              paste: true,
              selectAll: false,
            ),
            focusNode: _toFocusNode,
            style: STextStyles.field(context),
            onChanged: (value) {
              ref.read(desktopExchangeModelProvider)!.recipientAddress =
                  _toController.text;
              widget.enableNextChanged.call(_next());
            },
            decoration:
                standardInputDecoration(
                  "Enter the ${ref.watch(desktopExchangeModelProvider.select((value) => value!.receiveTicker.toUpperCase()))} payout address",
                  _toFocusNode,
                  context,
                  desktopMed: true,
                ).copyWith(
                  contentPadding: const EdgeInsets.only(
                    left: 16,
                    top: 6,
                    bottom: 8,
                    right: 5,
                  ),
                  suffixIcon: Padding(
                    padding: _toController.text.isEmpty
                        ? const EdgeInsets.only(right: 8)
                        : const EdgeInsets.only(right: 0),
                    child: UnconstrainedBox(
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.spaceAround,
                        children: [
                          _toController.text.isNotEmpty
                              ? TextFieldIconButton(
                                  key: const Key(
                                    "sendViewClearAddressFieldButtonKey",
                                  ),
                                  onTap: () {
                                    _toController.text = "";
                                    ref
                                            .read(desktopExchangeModelProvider)!
                                            .recipientAddress =
                                        _toController.text;
                                    widget.enableNextChanged.call(_next());
                                  },
                                  child: const XIcon(),
                                )
                              : TextFieldIconButton(
                                  key: const Key(
                                    "sendViewPasteAddressFieldButtonKey",
                                  ),
                                  onTap: () async {
                                    final ClipboardData? data = await clipboard
                                        .getData(Clipboard.kTextPlain);
                                    if (data?.text != null &&
                                        data!.text!.isNotEmpty) {
                                      final content = data.text!.trim();
                                      final paymentData =
                                          AddressUtils.parsePaymentUri(
                                            content,
                                            logging: Logging.instance,
                                          );
                                      if (paymentData != null) {
                                        _toController.text =
                                            paymentData.address;
                                        _setRecipientMemo(paymentData.memo);
                                      } else {
                                        _toController.text = content;
                                      }
                                      ref
                                          .read(desktopExchangeModelProvider)!
                                          .recipientAddress = _toController
                                          .text;
                                      widget.enableNextChanged.call(_next());
                                    }
                                  },
                                  child: _toController.text.isEmpty
                                      ? const ClipboardIcon()
                                      : const XIcon(),
                                ),
                          if (_toController.text.isEmpty &&
                              AppConfig.isStackCoin(
                                ref.watch(
                                  desktopExchangeModelProvider.select(
                                    (value) => value!.receiveTicker,
                                  ),
                                ),
                              ))
                            TextFieldIconButton(
                              key: const Key("sendViewAddressBookButtonKey"),
                              onTap: selectRecipientFromAddressBook,
                              child: const AddressBookIcon(),
                            ),
                        ],
                      ),
                    ),
                  ),
                ),
          ),
        ),
        if (_showRecipientMemo) const SizedBox(height: 10),
        if (_showRecipientMemo)
          Text(
            "Memo or destination tag",
            style: STextStyles.desktopTextExtraExtraSmall(context).copyWith(
              color: Theme.of(
                context,
              ).extension<StackColors>()!.textFieldActiveSearchIconRight,
            ),
          ),
        if (_showRecipientMemo) const SizedBox(height: 10),
        if (_showRecipientMemo)
          ClipRRect(
            borderRadius: BorderRadius.circular(
              Constants.size.circularBorderRadius,
            ),
            child: TextField(
              key: const Key("recipientExchangeStep2ViewMemoFieldKey"),
              controller: _toMemoController,
              focusNode: _toMemoFocusNode,
              autocorrect: false,
              enableSuggestions: false,
              style: STextStyles.field(context),
              onChanged: (value) {
                ref.read(desktopExchangeModelProvider)!.extraId = value.isEmpty
                    ? null
                    : value;
              },
              decoration: standardInputDecoration(
                "Enter the memo or tag required by the payout address, if any",
                _toMemoFocusNode,
                context,
                desktopMed: true,
              ),
            ),
          ),
        const SizedBox(height: 10),
        RoundedWhiteContainer(
          borderColor: Theme.of(context).extension<StackColors>()!.background,
          child: Text(
